{
  "css": "/* Booking Layout Wrapper */
#booking-layout {
  display: flex;
  flex-direction: column;
}

/* Host Section Typography */
.booking-host-title {
  font-size: 18px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--text-primary);
  margin-top: 8px;
}

.booking-host-subtitle {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-top: 4px;
}

/* Action Row Grid */
#booking-actions {
  display: grid;
  grid-template-columns: 48px minmax(0, 1fr);
  align-items: center;
  gap: 12px;
}

/* Favorite Icon Button */
.booking-icon-btn {
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: #f2f2f5;
  border-radius: 8px;
  border: none;
  padding: 0;
  cursor: pointer;
  transition: background-color 0.1s ease;
}

.booking-icon-btn img {
  width: 24px;
  height: 24px;
  display: block;
  object-fit: contain;
  color: var(--text-primary);
}

.booking-icon-btn[aria-pressed="true"] {
  background-color: #e6e1ff;
}

.booking-icon-btn[aria-pressed="true"] img {
  color: var(--action-bg);
}

.booking-icon-btn:active {
  transform: scale(0.96);
}

/* Primary Booking CTA */
.booking-primary-btn {
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  background-color: var(--action-bg);
  color: var(--action-fg);
  border: none;
  border-radius: 6px;
  padding-block: var(--action-pad-block);
  padding-inline: var(--action-pad-inline);
  font-size: 16px;
  font-weight: 700;
  line-height: 1.5;
  white-space: normal;
  width: 0; /* Force grid minmax to calculate width */
  min-width: 0;
  overflow-wrap: break-word;
  text-align: center;
}

/* Booking Note */
.booking-note {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.6;
  color: var(--text-secondary);
  margin-top: 12px;
  text-align: center;
}"
}
